// Publish live state for the dashboard. fs is an allowed builtin
// (NODE_FUNCTION_ALLOW_BUILTIN=fs); tmp + rename so nginx never serves a
// torn file. Containers come from the read-only docker-socket-proxy
// (/containers/json), not the host socket. If the proxy is unreachable the
// previous node errored through (onError) and we publish without the
// containers section — the dashboard simply hides it.
const fs = require('fs');
const rows = $input.all().map((i) => i.json).filter((c) => c && Array.isArray(c.Names));
const status = { generated_at: new Date().toISOString() };
if (rows.length) {
  status.containers = rows
    .map((c) => ({ name: (c.Names[0] || '').replace(/^\//, ''), image: c.Image, status: c.Status }))
    .sort((a, b) => a.name.localeCompare(b.name));
}
fs.writeFileSync('/po11y-status/status.json.tmp', JSON.stringify(status));
fs.renameSync('/po11y-status/status.json.tmp', '/po11y-status/status.json');
return [{ json: { published: true, containers: (status.containers || []).length } }];

// Build a mermaid graph of every workflow on this instance and how they
// link: trigger entry points (schedule/form/webhook), Execute Workflow
// references, plus best-effort webhook/form-call edges (an HTTP Request
// whose URL contains another workflow's webhook or form path).
// Writes /po11y-status/map.json for site/map.html.
const fs = require('fs');
const wfs = JSON.parse($json.stdout).filter((w) => !w.isArchived);
const esc = (s) => String(s || '').replace(/["`]/g, "'");
const nid = (id) => 'wf_' + String(id).replace(/[^A-Za-z0-9]/g, '_');
const lines = ['graph TD'];
const edges = new Set();
// hook paths per workflow: webhook + formTrigger nodes
const hooks = [];
for (const wf of wfs) {
  for (const n of wf.nodes || []) {
    const p = (n.parameters || {}).path;
    if (!p) continue;
    if (n.type === 'n8n-nodes-base.webhook') hooks.push({ path: `/webhook/${p}`, wf: wf.id });
    if (n.type === 'n8n-nodes-base.formTrigger') hooks.push({ path: `/form/${p}`, wf: wf.id });
  }
}
let t = 0;
for (const wf of wfs) {
  const label = esc(wf.name) + (wf.active ? '' : ' (inactive)');
  lines.push(`  ${nid(wf.id)}["${label}"]`);
  if (wf.active) lines.push(`  class ${nid(wf.id)} active`);
  for (const n of wf.nodes || []) {
    const prm = n.parameters || {};
    // trigger entry points as small round nodes
    let trig = '';
    if (n.type === 'n8n-nodes-base.scheduleTrigger') {
      const iv = ((prm.rule || {}).interval || [])[0] || {};
      const num = iv.minutesInterval || iv.hoursInterval || iv.secondsInterval || iv.daysInterval;
      const unit = { minutes: 'min', hours: 'h', seconds: 's', days: 'd' }[iv.field] || iv.field || '';
      trig = num ? `every ${num} ${unit}` : 'schedule';
    } else if (n.type === 'n8n-nodes-base.formTrigger') {
      trig = `form /${prm.path || '?'}`;
    } else if (n.type === 'n8n-nodes-base.webhook') {
      trig = `webhook /${prm.path || '?'}`;
    }
    if (trig) {
      const tid = `t${t++}`;
      lines.push(`  ${tid}(("${esc(trig)}"))`);
      lines.push(`  class ${tid} trigger`);
      edges.add(`  ${tid} --> ${nid(wf.id)}`);
    }
    // Execute Workflow: workflowId is a string (old) or {value} (resource locator)
    if (n.type === 'n8n-nodes-base.executeWorkflow') {
      const ref = typeof prm.workflowId === 'object' ? (prm.workflowId || {}).value : prm.workflowId;
      if (ref) edges.add(`  ${nid(wf.id)} -->|sub-workflow| ${nid(ref)}`);
    }
    // HTTP Request calling another workflow's webhook/form
    if (n.type === 'n8n-nodes-base.httpRequest' && typeof prm.url === 'string') {
      for (const h of hooks) {
        if (h.wf !== wf.id && prm.url.includes(h.path)) edges.add(`  ${nid(wf.id)} -.->|http| ${nid(h.wf)}`);
      }
    }
  }
}
lines.push(...edges);
lines.push('  classDef active stroke-width:3px');
lines.push('  classDef trigger stroke-dasharray:3 3,font-size:11px');
const out = { generated_at: new Date().toISOString(), mermaid: lines.join('\n'), workflows: wfs.length };
fs.writeFileSync('/po11y-status/map.json.tmp', JSON.stringify(out));
fs.renameSync('/po11y-status/map.json.tmp', '/po11y-status/map.json');
return [{ json: { published: true, workflows: wfs.length, edges: edges.size } }];

// Publish the live form-trigger inventory for the dashboard's Actions
// group: every active workflow's formTrigger nodes as { name, sub, path }.
// The dashboard (app.js) merges /forms.json into its Actions cards, so a
// new form trigger becomes a button without touching config.json.
const fs = require('fs');
const wfs = JSON.parse($json.stdout).filter((w) => !w.isArchived);
const forms = [];
for (const wf of wfs) {
  if (!wf.active) continue;
  for (const n of wf.nodes || []) {
    if (n.type !== 'n8n-nodes-base.formTrigger') continue;
    const p = n.parameters || {};
    const path = p.path || n.webhookId;
    if (!path) continue;
    forms.push({ name: p.formTitle || n.name, sub: p.formDescription || wf.name, path, fields: ((p.formFields || {}).values || []).length });
  }
}
const out = { generated_at: new Date().toISOString(), forms };
fs.writeFileSync('/po11y-status/forms.json.tmp', JSON.stringify(out));
fs.renameSync('/po11y-status/forms.json.tmp', '/po11y-status/forms.json');
return [{ json: { published: forms.length } }];

// Deterministic architecture map. Structure (columns, nodes, edges) is
// computed from the live export — the same references the mermaid map uses —
// so the layout is identical run-to-run. An optional LLM (AI_MAP_*) only
// writes prose: per-node one-liners, the lede, insight cards. Without a key
// the map publishes with heuristic text (ai-map-cli.sh can annotate via a
// local CLI instead). Annotation is differential: per-node content
// signatures (sigs) let unchanged nodes keep their previous prose, so the
// LLM only ever sees the workflows that actually changed.
const fs = require('fs');
const wfs = JSON.parse($json.stdout).filter((w) => !w.isArchived);
const cut = (s, n) => (typeof s === 'string' && s.length > n ? s.slice(0, n) + '…' : s);

// ---- skeleton ----------------------------------------------------------------
const TRIG = {
  'n8n-nodes-base.scheduleTrigger': 'schedule',
  'n8n-nodes-base.formTrigger': 'form',
  'n8n-nodes-base.webhook': 'webhook',
};
const wfCol = new Map(); // 1 = entry workflow, 2 = called sub-workflow
for (const wf of wfs) {
  const hasOwnTrigger = (wf.nodes || []).some((n) => TRIG[n.type]);
  const isCalled = (wf.nodes || []).some((n) => n.type === 'n8n-nodes-base.executeWorkflowTrigger');
  wfCol.set(wf.id, !hasOwnTrigger && isCalled ? 2 : 1);
}
const nodes = [], edgeSet = new Set(), files = new Set(), externals = new Set();
const edge = (a, b, k) => edgeSet.add(JSON.stringify([a, b, k]));
const firstComment = (wf) => {
  for (const n of wf.nodes || []) {
    const c = String((n.parameters || {}).jsCode || '').split('\n').find((l) => l.startsWith('//'));
    if (c) return cut(c.replace(/^\/\/\s*/, ''), 90);
  }
  return `${(wf.nodes || []).length} nodes`;
};
for (const wf of wfs) {
  const col = wfCol.get(wf.id);
  nodes.push({ id: 'wf:' + wf.id, col, kind: col === 2 ? 'worker' : 'entry',
    tag: col === 2 ? 'sub-workflow' : 'workflow', name: wf.name, sub: firstComment(wf) });
  for (const n of wf.nodes || []) {
    const p = n.parameters || {};
    const kind = TRIG[n.type];
    if (kind) {
      let tag;
      if (kind === 'schedule') {
        const iv = ((p.rule || {}).interval || [])[0] || {};
        const num = iv.minutesInterval || iv.hoursInterval || iv.secondsInterval || iv.daysInterval;
        const unit = { minutes: 'min', hours: 'h', seconds: 's', days: 'd' }[iv.field] || '';
        tag = num ? `every ${num} ${unit}` : 'schedule';
      } else tag = `/${kind}/${p.path || n.webhookId || '?'}`;
      const id = `t:${wf.id}:${n.name}`;
      nodes.push({ id, col: 0, kind, tag, name: n.name, sub: `starts ${wf.name}` });
      edge(id, 'wf:' + wf.id, kind);
    }
    if (n.type === 'n8n-nodes-base.executeWorkflow') {
      const ref = typeof p.workflowId === 'object' ? (p.workflowId || {}).value : p.workflowId;
      if (ref && wfCol.has(ref)) edge('wf:' + wf.id, 'wf:' + ref, 'worker');
    }
    const code = String(p.jsCode || '');
    for (const m of code.matchAll(/\/po11y-status\/([A-Za-z0-9_-]+\.json)/g)) {
      files.add(m[1]);
      edge('wf:' + wf.id, 'f:' + m[1], 'file');
    }
    // regex host extraction — URL/globals can be absent in the Code sandbox
    const hay = code + ' ' + (typeof p.url === 'string' ? p.url : '');
    for (const m of hay.matchAll(/https?:\/\/([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g)) {
      const host = m[1];
      if (/localhost|127\.0\.0\.1/.test(host)) continue;
      externals.add(host);
      edge('wf:' + wf.id, 'x:' + host, 'external');
    }
  }
}
for (const f of files) nodes.push({ id: 'f:' + f, col: 3, kind: 'file', tag: 'feed', name: '/' + f, sub: 'dashboard feed' });
for (const h of externals) nodes.push({ id: 'x:' + h, col: 3, kind: 'external', tag: 'external', name: h, sub: 'external service' });
nodes.sort((a, b) => a.col - b.col || a.name.localeCompare(b.name) || a.id.localeCompare(b.id));
const edges = [...edgeSet].sort().map((e) => JSON.parse(e));

const KIND_LABEL = { schedule: 'Schedule trigger', form: 'Form trigger', webhook: 'Webhook trigger',
  entry: 'Workflow', worker: 'Sub-workflow', file: 'Published feed', external: 'External service' };
const map = {
  eyebrow: 'po11y · architecture',
  title: 'How the workflows link',
  lede: 'Triggers on the left start the workflows; edges follow real references (sub-workflow calls, published feeds, external services).',
  columns: ['Triggers', 'Workflows', 'Sub-workflows', 'Outputs'],
  kinds: { schedule: 'sky', form: 'amber', webhook: 'violet', entry: 'cyan', worker: 'emerald', file: 'sink', external: 'neutral' },
  nodes, edges,
  legend: Object.keys(KIND_LABEL).filter((k) => nodes.some((n) => n.kind === k)).map((k) => [KIND_LABEL[k], k]),
  notes: [],
};

// ---- change detection ----------------------------------------------------------
// One digest entry per workflow (also the LLM's context). A node's signature
// hashes the digest of the workflow it belongs to, so prose is re-generated
// for exactly the nodes whose underlying workflow changed.
const digestOf = (wf) => ({
  id: wf.id, name: wf.name, active: !!wf.active,
  nodes: (wf.nodes || []).map((nd) => {
    const p = nd.parameters || {};
    const o = { name: nd.name, type: nd.type.replace('n8n-nodes-base.', '') };
    if (p.rule) o.rule = p.rule;
    if (p.path) o.path = p.path;
    if (p.url) o.url = cut(p.url, 120);
    if (p.command) o.command = cut(p.command, 160);
    if (p.workflowId) o.calls = typeof p.workflowId === 'object' ? p.workflowId.value : p.workflowId;
    if (p.jsCode) o.code_comment = cut(String(p.jsCode).split('\n').filter((l) => l.startsWith('//')).join(' '), 300);
    return o;
  }),
});
const digest = wfs.map(digestOf);
const digestJson = new Map(digest.map((d) => [d.id, JSON.stringify(d)]));
const hash = (s) => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0; return h.toString(36); };
const wfIdOf = (id) => id.startsWith('wf:') ? id.slice(3) : id.startsWith('t:') ? id.split(':')[1] : null;
const sigs = {};
for (const n of nodes) {
  const w = wfIdOf(n.id);
  sigs[n.id] = hash((w ? digestJson.get(w) || '' : '') + '|' + n.tag + '|' + n.name);
}
map.sigs = sigs;

// ---- publish policy ------------------------------------------------------------
let prev = null;
try { prev = JSON.parse(fs.readFileSync('/po11y-status/ai-map.json', 'utf8')); } catch {}
const sameStructure = !!prev && Array.isArray(prev.nodes) && prev.nodes.length === nodes.length
  && nodes.every((n) => prev.nodes.some((o) => o.id === n.id));
const sameContent = sameStructure && !!prev.sigs && nodes.every((n) => prev.sigs[n.id] === sigs[n.id]);
const prevAnnotated = !!prev && !!prev.model && prev.model !== 'heuristic';
let forced = false;
try { forced = $('Build now (form)').all().length > 0; } catch {}
const prevAge = prev ? Date.now() - new Date(prev.generated_at).getTime() : Infinity;
const fresh = prevAge < 20 * 3600 * 1000;
// AI config from a non-served file (bootstrap renders it from .env).
// Environment access is blocked in Code nodes, so workflows cannot
// read the DB / Grafana passwords out of the process environment.
let AICFG = {};
try { AICFG = JSON.parse(fs.readFileSync('/run/po11y/ai-map.json', 'utf8')); } catch {}
const KEY = AICFG.api_key || '';
const MODEL = AICFG.model || '';
const BASE = (AICFG.base_url || '').replace(/\/$/, '');
const aiConfigured = KEY && MODEL && BASE;
if (sameStructure && fresh && !forced) return [{ json: { skipped: 'fresh' } }];
if (!aiConfigured && sameStructure && prevAnnotated && !forced) {
  return [{ json: { skipped: 'structure unchanged; keeping annotated map' } }];
}
if (sameContent && !forced && (prevAnnotated || !aiConfigured)) {
  // Content-identical map — refresh the timestamp, spend no LLM tokens.
  prev.generated_at = new Date().toISOString();
  fs.writeFileSync('/po11y-status/ai-map.json.tmp', JSON.stringify(prev));
  fs.renameSync('/po11y-status/ai-map.json.tmp', '/po11y-status/ai-map.json');
  return [{ json: { republished: 'content unchanged — no LLM call' } }];
}

// ---- optional LLM annotation (prose only; structure stays fixed) ----------------
if (aiConfigured) {
  // Differential: nodes whose signature is unchanged keep their previous
  // prose; only changed/new nodes (and their workflows' digest) go to the
  // LLM. A forced rebuild (the form) re-annotates everything.
  const prevSubs = new Map(((prev || {}).nodes || []).map((o) => [o.id, o.sub]));
  let target = nodes;
  if (!forced && prevAnnotated && prev.sigs) {
    target = nodes.filter((n) => prev.sigs[n.id] !== sigs[n.id] || !prevSubs.get(n.id));
    for (const n of nodes) if (!target.includes(n) && prevSubs.get(n.id)) n.sub = prevSubs.get(n.id);
  }
  const partial = target.length < nodes.length;
  if (partial) {
    // Mostly the same stack — the previous lede/notes still describe it.
    if (typeof prev.lede === 'string' && prev.lede) map.lede = prev.lede;
    if (Array.isArray(prev.notes)) map.notes = prev.notes;
  }
  if (partial && !target.length) {
    // Node set shrank but every remaining node is unchanged — nothing to ask.
    map.model = prev.model;
  } else {
    const targetWfIds = new Set(target.map((n) => wfIdOf(n.id)).filter(Boolean));
    const sendDigest = partial ? digest.filter((d) => targetWfIds.has(d.id)) : digest;
    const skeleton = JSON.stringify(nodes.map(({ id, kind, tag, name }) => ({ id, kind, tag, name })));
    const prompt = partial
      ? `You annotate a fixed architecture map of an n8n automation stack. Only the listed node ids changed — you ONLY write text for those.\n\nReturn STRICT JSON (no markdown): {"subs": {"<node id>": "concrete one-line description, max 90 chars"}}\n\nRules: cover exactly these node ids: ${JSON.stringify(target.map((n) => n.id))}; 'subs' must say what the thing concretely does (use the digest's code comments).\n\nAll map nodes (context):\n${skeleton}\n\nDigest of the changed workflows:\n${JSON.stringify(sendDigest)}`
      : `You annotate a fixed architecture map of an n8n automation stack. The structure is already decided — you ONLY write text.\n\nReturn STRICT JSON (no markdown): {"lede": "1-2 sentences describing the left-to-right flow", "subs": {"<node id>": "concrete one-line description, max 90 chars"}, "notes": [{"title": "short", "text": "2-3 sentences of real operational insight"}]}\n\nRules: cover every node id; 'subs' must say what the thing concretely does (use the digest's code comments); notes max 3, skip generic filler.\n\nMap nodes:\n${skeleton}\n\nWorkflow digest:\n${JSON.stringify(sendDigest)}`;
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: `${BASE}/chat/completions`,
      headers: { Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' },
      body: { model: MODEL, messages: [{ role: 'user', content: prompt }], response_format: { type: 'json_object' }, max_tokens: 3000 },
      json: true,
    });
    let text = ((res.choices || [])[0] || {}).message?.content || '';
    text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    try {
      const ann = JSON.parse(text);
      for (const n of target) {
        const s = (ann.subs || {})[n.id];
        if (typeof s === 'string' && s.trim()) n.sub = cut(s.trim(), 120);
      }
      if (!partial) {
        if (typeof ann.lede === 'string' && ann.lede.trim()) map.lede = cut(ann.lede.trim(), 240);
        map.notes = (Array.isArray(ann.notes) ? ann.notes : []).slice(0, 3)
          .filter((x) => x && x.title && x.text)
          .map((x) => ({ title: cut(String(x.title), 60), text: cut(String(x.text), 400) }));
      }
      map.model = MODEL;
    } catch (e) {
      console.log('ai-map: annotation unusable, keeping previous/heuristic text — ' + e.message);
      map.model = partial ? (prev.model || 'heuristic') : 'heuristic';
    }
  }
} else {
  map.model = 'heuristic';
}
map.generated_at = new Date().toISOString();
fs.writeFileSync('/po11y-status/ai-map.json.tmp', JSON.stringify(map));
fs.renameSync('/po11y-status/ai-map.json.tmp', '/po11y-status/ai-map.json');
return [{ json: { published: true, model: map.model, nodes: nodes.length, edges: edges.length } }];
